@Test
    public void testEncodeChunkedURLSafe() {
        byte[] input = {'a', 'b', 'c', 'd'};
        byte[] expected = {'DGY2', 'DQY2', 'DQY2', 'DQY2'};
        byte[] actual = Base64.encodeBase64(input, true, true, 0);
        Assert.assertArrayEquals(expected, actual);
    }


@Before
    public void setUp() {
        base64 = new Base64();
    }


@Test
    public void testEncodeLargeByteArray() {
        byte[] input = new byte[1000];
        for(int i = 0; i < 1000; i++) {
            input[i] = (byte) (i % 256);
        }
        byte[] expected = Base64.encodeBase64(input, false, false, 0);
        Assert.assertEquals(expected, input);
    }


@Test
    public void testEncodeURLSafe() {
        byte[] input = {'a', 'b', 'c', 'd'};
        byte[] expected = {'DGY2', 'DQY2', 'DQY2', 'DQY2'};
        byte[] actual = Base64.encodeBase64(input, false, true, 0);
        Assert.assertArrayEquals(expected, actual);
    }


@Test
    public void testEncodeChunked() {
        byte[] input = {'a', 'b', 'c', 'd'};
        byte[] expected = {'DGY2', 'DQY2', 'DQY2', 'DQY2'};
        byte[] actual = Base64.encodeBase64(input, true, false, 0);
        Assert.assertArrayEquals(expected, actual);
    }


