    public void testEncodeEmptyByteArray() {
        byte[] input = {};
        byte[] expected = {};
        byte[] actual = Base64.encodeBase64(input, false, false, 0);
        Assert.assertEquals(expected, actual);
    }


@Test
    public void testEncodeMaxResultSize() {
        byte[] input = new byte[1024];
        for (int i = 0; i < 1024; i++) {
            input[i] = (byte) (i % 256);
        }
        boolean exceptionThrown = false;
        try {
            Base64.encodeBase64(input, false, false, 100);
        } catch (IllegalArgumentException e) {
            exceptionThrown = true;
        }
        Assert.assertTrue(exceptionThrown);
    }


@Test
    public void testEncodeNonEmptyByteArray() {
        byte[] input = {'a', 'b', 'c', 'd'};
        byte[] expected = {'zaXRvcnkn','zaXRvcnkn','zaXRvcnkn','zaXRvcnkn'};
